local config = {
  ui_story_32040401_1_dialog_content = "Let me count them one last time. One, two, three... Yep, that's all of them!",
  ui_story_32040401_2_dialog_content = "There's all kinds of stuff here from around the world. Illumina, the Rediesel Desert... There's even stuff from Longzhou in here!",
  ui_story_32040401_3_dialog_content = "May I ask what all of these things are for, Lady Joshua?",
  ui_story_32040401_4_dialog_content = "Oh, these are just <color=#FFB400>gifts</color> that I picked up during my travels.",
  ui_story_32040401_5_dialog_content = "Ever since leaving Lumopolis, I've come across all manner of new and wonderful things.",
  ui_story_32040401_6_dialog_content = "During a recent visit to Northland, I learned just how isolated and reserved the people can be in this nation.",
  ui_story_32040401_7_dialog_content = "And so, I began looking for a way to share my exciting experiences with the children.",
  ui_story_32040401_8_dialog_content = "So you've been gathering gifts from all over the world just for them?",
  ui_story_32040401_9_dialog_content = "Indeed. I pray that my gifts will pique their youthful curiosity, and give them a glimpse of the true vastness of our world.",
  ui_story_32040401_10_dialog_content = "In the unforgiving sands of the Rediesel Desert, a group of Aurorians discovered a way to survive together on the virtues of loyalty and comradery.",
  ui_story_32040401_11_dialog_content = "And in the Illumina Federation, a single wall stands between a war-torn battlefield and a simple, yet fulfilling life.",
  ui_story_32040401_12_dialog_content = "In Twin Pavilions Bay, I even met a traveler hailing from Longzhou, a land lying far across the ocean. Their culture and history differ so much from that of Astra...",
  ui_story_32040401_13_dialog_content = "If these children can understand the great size of our world, perhaps they will have even more to look forward to in this life.",
  ui_story_32040401_14_dialog_content = "So much thought was put into such little gifts... You're incredible, Lady Joshua!",
  ui_story_32040401_15_dialog_content = "Hahaha, I wouldn't go that far. Besides, this may help me make up for some of <color=#FFB400>my past regrets</color>.",
  ui_story_32040401_16_dialog_content = "My apologies for the delay, Lady Joshua—Hmm? What a surprise to see you here as well, PlayerName.",
  ui_story_32040401_17_dialog_content = "Hey there, Novio! So you're the person Lady Joshua was waiting for!",
  ui_story_32040401_18_dialog_content = "Indeed. Mr. Novio has graciously agreed to help me gather the children, so that I may hand out their gifts.",
  ui_story_32040401_19_dialog_content = "Think nothing of it.",
  ui_story_32040401_20_dialog_content = "<size=33>Does Novio know about your situation, Lady Joshua?</size>",
  ui_story_32040401_21_dialog_content = "<size=33>He has yet to make any mention of it, though I'm certain he must have some idea by now.</size>",
  ui_story_32040401_22_dialog_content = "The children are ready and waiting, my friends. We may leave once you load the gifts onto the carriage.",
  ui_story_32040401_23_dialog_content = "Wow! So many presents!",
  ui_story_32040401_24_dialog_content = "Is this an instrument from Longzhou? I've never seen anything like this before...",
  ui_story_32040401_25_dialog_content = "A game machine from Illumina! I want that one!",
  ui_story_32040401_26_dialog_content = "Settle down, children. There are plenty of gifts for everyone.",
  ui_story_32040401_27_dialog_content = "Phew... That was a lot more tiring than I thought it would be. I had no idea there would be so many kids!",
  ui_story_32040401_28_dialog_content = "Your hard work is most appreciated. Might I offer you a refreshment?",
  ui_story_32040401_29_dialog_content = "Sure! And thanks again for sticking around, Novio. I don't think Lady Joshua and I could've handled all those kids without your help.",
  ui_story_32040401_30_dialog_content = "We are the same in that respect, are we not? It was my understanding that you were only meant to help with transporting the gifts, yet you chose to stay and help us.",
  ui_story_32040401_31_dialog_content = "Well, I couldn't just leave without offering to help; she's a good friend after all. Besides, it was for a good cause!",
  ui_story_32040401_32_dialog_content = "Still, I wasn't expecting you to help Lady Joshua with promoting cultures from outside of Northland.",
  ui_story_32040401_33_dialog_content = "She merely wishes to enrich the lives of our young children by broadening their horizons. Her motives are pure, of that I have no doubt.",
  ui_story_32040401_34_dialog_content = "Not only that... Queen Bethlehem once had an elder sister who married a former governor of Lumopolis, and left Northland to be with him.",
  ui_story_32040401_35_dialog_content = "A former governor of Lumopolis?",
  ui_story_32040401_36_dialog_content = "Perhaps... Or perhaps it was the one before that? My recollection is somewhat hazy. At the time, I was but a mere mountain spirit, and I was hardly concerned in matters of governance.",
  ui_story_32040401_37_dialog_content = "All that I remember was the look of loneliness on her face when she departed from the palace.",
  ui_story_32040401_38_dialog_content = "As well as... Queen Bethlehem's expression when her remains were sent back to be laid to rest.",
  ui_story_32040401_39_dialog_content = "Back then, I could not help the poor lady, and now... Ah, please forgive me. I shouldn't trouble you with such dull matters of the past.",
  ui_story_32040401_40_dialog_content = "(So even Novio has his own share of regrets, huh...)",
  ui_story_32040401_41_dialog_content = "Excuse me? Were you the ones who brought us all these gifts?",
  ui_story_32040401_42_dialog_content = "Huh? Why yes, we did! If you'd like one, just go talk to the nice, white-haired lady over there.",
  ui_story_32040401_43_dialog_content = "I don't want any gifts. I just want to ask you a question.",
  ui_story_32040401_44_dialog_content = "Why did you go through the trouble of bringing us presents from the outside world? What's in it for you?",
  ui_story_32040401_45_dialog_content = "And why are you helping them, Lord Novio? Didn't you say that Northland is the last paradise left for Aurorians...?",
  ui_story_32040401_46_dialog_content = "(Oh, what a pointed question... what happened to this little girl?)",
  ui_story_32040401_47_dialog_content = "Oh my, not this again... Please do not take offense, PlayerName.",
  ui_story_32040401_48_dialog_content = "This child dreams of becoming a knight to protect all of Northland. She has proven herself to be quite gifted for a child of her age.",
  ui_story_32040401_49_dialog_content = "However, she still has room to grow with regard to interpersonal communication. I apologize if her questions were a bit too forthright.",
  ui_story_32040401_50_dialog_content = "As for you, my child, rest assured that PlayerName and Lady Joshua bear us no ill will in the slightest.",
  ui_story_32040401_51_dialog_content = "Now come, apologize to our guests.",
  ui_story_32040401_52_dialog_content = "... Sorry.",
  ui_story_32040401_53_dialog_content = "Listen closely, little one. If you truly wish to defend Northland as a knight in service to the queen, you must learn to treat others with courtesy and consideration.",
  ui_story_32040401_54_dialog_content = "While your honesty and sincerity are commendable, being too forthright can sometimes create more problems, both for yourself and for the people you love.",
  ui_story_32040401_55_dialog_content = "So you're saying I shouldn't tell the truth?",
  ui_story_32040401_56_dialog_content = "No child, that's certainly not what I meant... I ask that you refrain from twisting my words like that.",
  ui_story_32040401_57_dialog_content = "(Hahaha... I guess this is what they mean by child-like innocence, huh?)",
  ui_story_32040401_58_dialog_content = "...",
  ui_story_32040401_59_dialog_content = "I didn't mean to upset Lord Novio. But I don't understand why I can't tell what I really think all the time...",
  ui_story_32040401_60_dialog_content = "Hello, my dear.",
  ui_story_32040401_61_dialog_content = "I-It's you! What exactly are you up to?!",
  ui_story_32040401_62_dialog_content = "<size=33>Wait, no... Lord Novio said I have to treat others with courtesy.</size>",
  ui_story_32040401_63_dialog_content = "... Thank you for bringing us presents.",
  ui_story_32040401_64_dialog_content = "You don't have to thank me, little one. After all, you haven't gotten a gift yet.",
  ui_story_32040401_65_dialog_content = "And is that not the truth you with to speak about?",
  ui_story_32040401_66_dialog_content = "Huh? H-How did you know?!",
  ui_story_32040401_67_dialog_content = "Heehee, it's written all over your adorable little face.",
  ui_story_32040401_68_dialog_content = "Emm... W-Well I can't help it! It's all because I don't understand!",
  ui_story_32040401_69_dialog_content = "Lord Novio said that the Aurorians outside of Northland couldn't unite under a single cause, and that's why Eclipsites roam all over the land.",
  ui_story_32040401_70_dialog_content = "But those adults still ask you to come here and tell us all about how fun it is out there?!",
  ui_story_32040401_71_dialog_content = "D-Doesn't that mean he's just letting you trick us...?",
  ui_story_32040401_72_dialog_content = "Hmm, it's certainly a very complicated subject, but for a child your age to understand this much... You are quite an incredible little girl.",
  ui_story_32040401_73_dialog_content = "... Huh?",
  ui_story_32040401_74_dialog_content = "To be sure, there is no other place in all of Astra as peaceful and sacred as Northland.",
  ui_story_32040401_75_dialog_content = "But different people from different places have their own ways of living. I simply wanted you and your friends to understand that.",
  ui_story_32040401_76_dialog_content = "By knowing this, you will be better equipped to forge a brighter future for yourselves.",
  ui_story_32040401_77_dialog_content = "And even after learning more about the world, it's perfectly fine if you still love Northland more than any other place.",
  ui_story_32040401_78_dialog_content = "Oh... Um...",
  ui_story_32040401_79_dialog_content = "Y-You're not just telling me what I want to hear, right...?",
  ui_story_32040401_80_dialog_content = "Hahaha! My, you really are an inquisitive little one.",
  ui_story_32040401_81_dialog_content = "In fact, you remind me very much of someone I know...",
  ui_story_32040401_82_dialog_content = "I have one last thing I wish to share with you, child. You are free to believe my words or not, so long as you give them some thought.",
  ui_story_32040401_83_dialog_content = "Your honest and forthright way of speaking might give others the impression that you are too outspoken or even immature.",
  ui_story_32040401_84_dialog_content = "But I know that's not the case. You're far more careful and considerate than many adults, and you have something important that you wish to protect.",
  ui_story_32040401_85_dialog_content = "This, in turn, is the reason you do not lower your guard so easily.",
  ui_story_32040401_86_dialog_content = "Your cautious, protective nature is the root of your so-called impoliteness.",
  ui_story_32040401_87_dialog_content = "Still, even someone like you requires a confidant, someone with whom you can talk freely about your worries without fear of being led astray.",
  ui_story_32040401_88_dialog_content = "Otherwise, those same worries will continue to build up, and eventually turn you into a short-sighted and even hostile person.",
  ui_story_32040401_89_dialog_content = "It may be some time before you find a confidant like this. Until then, keep your shortcomings in mind, and don't let them get the better of you.",
  ui_story_32040401_90_dialog_content = "...",
  ui_story_32040401_91_dialog_content = "I'm sorry... Was that too complicated for you?",
  ui_story_32040401_92_dialog_content = "N-Not at all! I understand!",
  ui_story_32040401_93_dialog_content = "Even though some of the words were a little hard to understand... I still think you're right!",
  ui_story_32040401_94_dialog_content = "S-So would it be okay if... if we became friends? Will you listen to me and keep me from going astray?",
  ui_story_32040401_95_dialog_content = "Me?",
  ui_story_32040401_96_dialog_content = "Yes, you! You're the first person to understand me so well!",
  ui_story_32040401_97_dialog_content = "I... If you don't mind, then I would be honored.",
  ui_story_32040401_98_dialog_content = "Hooray!!!",
  ui_story_32040401_99_dialog_content = "My help... to guide the others?",
  ui_story_32040401_100_dialog_content = "You aren't required to have tea with the other noble wives if you don't wish to do so, Joshua.",
  ui_story_32040401_101_dialog_content = "A new governor will be elected soon. For you to win and establish your prestige, I must play the role of a perfect noble wife.",
  ui_story_32040401_102_dialog_content = "Now is not the time to do as I wish.",
  ui_story_32040401_103_dialog_content = "But Joshua, what will change if we become the next rulers of Lumopolis by catering to the whims of those decrepit aristocrats?",
  ui_story_32040401_104_dialog_content = "We would be nothing more than puppets of the nobility, in that case.",
  ui_story_32040401_105_dialog_content = "Well said, Daniel, but your father's supporters have already sided against us.",
  ui_story_32040401_106_dialog_content = "Those centrists don't give a damn about politics, but if we don't enlist their aid, what chance do we have of winning?!",
  ui_story_32040401_107_dialog_content = "I was under the impression you were playing the role of a perfect noble wife. Why are you showing me such a hostile side of yourself to me again?",
  ui_story_32040401_108_dialog_content = "I'm sorry, I was just...",
  ui_story_32040401_109_dialog_content = "I know you are worried about the election.",
  ui_story_32040401_110_dialog_content = "And compared to when we first met, you've become a much more kind and gentle person... One who smiles a lot more as well.",
  ui_story_32040401_111_dialog_content = "Which is why I don't want you to turn back into the person you once were: someone who must wear a disguise at all times for the sake of accomplishing a distant goal.",
  ui_story_32040401_112_dialog_content = "I... I just don't know how to proceed, especially when those air-headed noblewomen laugh and ridicule the people of Lower Lumopolis.",
  ui_story_32040401_113_dialog_content = "But I don't want to lose their support over this either.",
  ui_story_32040401_114_dialog_content = "Hahaha... I understand completely. Not a single one of those aristocrats thinks that I can forge my own path.",
  ui_story_32040401_115_dialog_content = "What we're doing right now is exploring a new direction, so that we may become worthy of guiding others towards a better future. Because of this, we have no one to lead us down the road which lies before us.",
  ui_story_32040401_116_dialog_content = "But at the very least, we will have each other.",
  ui_story_32040401_117_dialog_content = "We may not have the right answers for each other every single time, but we can share our burdens with one another, and keep ourselves from going astray.",
  ui_story_32040401_118_dialog_content = "You're right. The path to our ideal future will not be easy to traverse... But at least, I will always have a trustworthy comrade to rely upon.",
  ui_story_32040401_119_dialog_content = "Sigh... It's times like these that you should refer to us as husband and wife, or at the very least partners...",
  ui_story_32040401_120_dialog_content = "There you are, Lady Joshua! I've been looking everywhere for you!",
  ui_story_32040401_121_dialog_content = "Oh! Sorry, PlayerName, I must have gotten lost.",
  ui_story_32040401_122_dialog_content = "I'm just relieved to see that you're okay. Let's head back to Soroz, shall we?",
  ui_story_32040401_123_dialog_content = "PlayerName... May I ask you a question?",
  ui_story_32040401_124_dialog_content = "Huh? Sure.",
  ui_story_32040401_125_dialog_content = "You are friends with Carleen and Veronica—I mean, Mia... Yes?",
  ui_story_32040401_126_dialog_content = "Could you tell me how the two of them are faring as of late?",
  ui_story_32040401_127_dialog_content = "As their parents, do you think Daniel and I... Did a good job of raising them?",
  ui_story_32040401_128_option_content = "Of course! You're such a kind person.",
  ui_story_32040401_129_dialog_content = "Of course you two did! Lord Schwartz is such a dignified and intelligent person, and you're one of the kindest and most gentle people I've ever met.",
  ui_story_32040401_130_dialog_content = "I'm positive Mia and Carleen learned a lot from both of you!",
  ui_story_32040401_131_dialog_content = "I see... Thank you.",
  ui_story_32040401_132_option_content = "I don't know, but I'm sure you did your best.",
  ui_story_32040401_133_dialog_content = "I, uh... I'm not Mia or Carleen, so I really don't have the right to judge their upbringing, you know?",
  ui_story_32040401_134_dialog_content = "Perfectly true, yes.",
  ui_story_32040401_135_dialog_content = "But when I see what you and Lord Schwartz have gone through, I think I might have an idea.",
  ui_story_32040401_136_dialog_content = "The two of you have always been willing to fight for the sake of your family and your ideals... Which is something they definitely learned from you.",
  ui_story_32040401_137_dialog_content = "Thank you, dear child. Your affirmation is more meaningful to me than any of the empty flattery I was once accustomed to hearing. From the bottom of my heart, thank you.",
  ui_story_32040401_138_dialog_content = "Y-You don't have to be so courteous! I was just saying what was on my mind, that's all!",
  ui_story_32040401_139_dialog_content = "Very well. Let's change the subject to something more cheerful.",
  ui_story_32040401_140_dialog_content = "Why don't we talk about our latest adventures on the way back to the Colossus?",
  ui_story_32040401_141_dialog_content = "After all, I'm nothing more than a solitary traveler now. All I have to offer are my experiences from around the world."
}
return config
